node -e 'const fs = require("fs")
const f = "components/help/help-markdown.tsx"
if (!fs.existsSync(f)) { console.error("SCAN-805: " + f + " is missing"); process.exit(79) }
const s = fs.readFileSync(f, "utf8")
const h2 = /h2:\s*\([^)]*\)\s*=>\s*\(?\s*<h2\b[^>]*>/.exec(s)
const h3 = /h3:\s*\([^)]*\)\s*=>\s*\(?\s*<h3\b[^>]*>/.exec(s)
const hasId = (m) => !!m && /\sid=/.test(m[0])
const slugPlugin = /rehype-slug|rehypeSlug/.test(s)
if (!(slugPlugin && /\bid\b/.test(s)) && !(hasId(h2) && hasId(h3))) { console.error("SCAN-805: the help markdown h2 and h3 handlers render no id attribute and no rehype-slug plugin is wired, so no section of any help article, the changelog or the training library can be linked to by URL."); process.exit(1) }
'
